def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, mod)

    size = len(alphabet)
    char_index = {char: i for i, char in enumerate(alphabet)}
    transitions = [[-1] * size]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for char in word:
            i = char_index[char]
            if transitions[state][i] == -1:
                transitions[state][i] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][i]
        forbidden[state] = True

    queue = deque()
    for i in range(size):
        child = transitions[0][i]
        if child == -1:
            transitions[0][i] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]
        for i in range(size):
            child = transitions[state][i]
            if child == -1:
                transitions[state][i] = transitions[failure[state]][i]
            else:
                failure[child] = transitions[failure[state]][i]
                queue.append(child)

    good_states = [state for state in range(len(transitions))
                   if not forbidden[state]]
    index = {state: i for i, state in enumerate(good_states)}
    count = len(good_states)

    matrix = [[0] * count for _ in range(count)]
    for state in good_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not forbidden[target]:
                row[index[target]] += 1

    vector = [0] * count
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, ways in enumerate(matrix[i]):
                        result[j] += value * ways
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                row = squared[i]
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, ways in enumerate(matrix[k]):
                            row[j] += value * ways
                squared[i] = [value % mod for value in row]
            matrix = squared

    return sum(vector) % mod
